from typing import Literal, Union, Optional

import pydantic

from ...schemas.rapi.base import BaseRapiResponseSchema


class SurveyCreateResultsSchema(pydantic.BaseModel):
    surveyId: str


class SurveyCreateResponseSchema(BaseRapiResponseSchema):
    results: SurveyCreateResultsSchema


class SurveyUpdateResponseSchema(BaseRapiResponseSchema): ...


class SurveyDeleteResponseSchema(BaseRapiResponseSchema): ...


class SurveyCopyResponseSchema(SurveyCreateResponseSchema): ...


class SurveyStartResultsSchema(pydantic.BaseModel):
    surveyId: str
    name: str
    description: str
    creator: str
    create: int
    start: int
    stop: int
    thanks: str
    active: bool
    forwarding: bool
    targets: list[str]
    flags: list[Literal["anonymous"]]
    image: str


class SurveyStartResponseSchema(BaseRapiResponseSchema):
    results: SurveyStartResultsSchema


class SurveyStopResponseSchema(SurveyStartResponseSchema): ...


class SurveyBeginResponseSchema(BaseRapiResponseSchema): ...


class Value(pydantic.BaseModel):
    min: list[Union[int, str]]
    max: list[Union[int, str]]


class Vote(pydantic.BaseModel):
    name: Optional[str] = None
    count: int
    responders: list[str]
    number: Optional[int] = None


class QuestionResult(pydantic.BaseModel):
    questionId: str
    name: str
    number: int
    typeQuestion: str
    flags: list[str]
    values: Union[list[str], Value]
    votes: list[Vote]


class SurveyResultsResultsSchema(pydantic.BaseModel):
    surveyId: str
    name: str
    countResponders: int
    stop: int
    image: str
    questionResults: list[QuestionResult]


class SurveyResultsResponseSchema(BaseRapiResponseSchema):
    results: SurveyResultsResultsSchema


class SurveyVoteResponseSchema(BaseRapiResponseSchema): ...


class Survey(pydantic.BaseModel):
    surveyId: str
    name: str
    creator: str
    active: bool
    create: int
    start: int
    stop: int
    countQuestions: int
    countResponders: int
    passedResponders: int
    flags: list[str]


class SurveyListResultsSchema(pydantic.BaseModel):
    surveys: list[Survey]


class SurveyListResponseSchema(BaseRapiResponseSchema):
    results: SurveyListResultsSchema


class Question(pydantic.BaseModel):
    questionId: str
    name: str
    number: int
    typeQuestion: str
    flags: list[str]
    values: Union[list[str], Value]


class SurveyGetResultsSchema(SurveyStartResultsSchema):
    passed: bool
    lastQuestionId: str
    questions: list[Question]


class SurveyGetResponseSchema(BaseRapiResponseSchema):
    results: SurveyGetResultsSchema


class SurveyQuestionsCreateResultsSchema(pydantic.BaseModel):
    questionId: str


class SurveyQuestionsCreateResponseSchema(BaseRapiResponseSchema):
    results: SurveyQuestionsCreateResultsSchema


class SurveyQuestionsUpdateResponseSchema(BaseRapiResponseSchema): ...


class SurveyQuestionsDeleteResponseSchema(BaseRapiResponseSchema): ...


class SurveyQuestionsChangeResponseSchema(BaseRapiResponseSchema): ...


class BaseQuestionResult(pydantic.BaseModel):
    name: str
    count: int
    responders: list[str]


class SurveyQuestionsRespondersResultsSchema(pydantic.BaseModel):
    countResponders: int
    typeQuestion: str
    questionResults: list[BaseQuestionResult]


class SurveyQuestionsRespondersResponseSchema(BaseRapiResponseSchema):
    results: SurveyQuestionsRespondersResultsSchema
